#!/usr/bin/env python3
"""dock/flexpepdock_peptide — auto-generated run.py (archetype=docking).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "docking"
BRAIN = "dock"
SKILL = "flexpepdock_peptide"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'flexpepdock_peptide', 'receptor': '', 'ligand': '', 'best_affinity': 0.0, 'poses': [{'rank': 1, 'affinity_kcal_per_mol': 0.0, 'pose_path': ''}], 'runtime_sec': 0.0, 'diagnostics': {'brain': 'dock', 'archetype': 'docking'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """PyRosetta FlexPepDock — 多肽-蛋白 docking。
    host_env=DL-masif(那里装了 pyrosetta);peptide ≤ 20 aa(>20 reject)。

    输入:start_pdb (含 receptor + peptide chain) / peptide_chain (默认 'B') /
          n_decoys (默认 50) / score_filter (默认 -200) / lowres (默认 False)
    输出:n_decoys / best_score / best_decoy_path / decoy_summary (top-10) / runtime_sec
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    start_pdb = payload.get("start_pdb") or payload.get("input_pdb")
    peptide_chain = payload.get("peptide_chain", "B")
    n_decoys = int(payload.get("n_decoys", 50))
    lowres = bool(payload.get("lowres", False))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="flexpepdock_")

    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_decoys": n_decoys, "peptide_chain": peptide_chain,
                   "lowres": lowres, "out_dir": out_dir}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "receptor": start_pdb or "", "ligand": peptide_chain,
                "best_affinity": 0.0,
                "poses": [{"rank": 1, "affinity_kcal_per_mol": 0.0, "pose_path": ""}],
                "runtime_sec": 0.0,
                "diagnostics": {**diagnostics, "dry": True}}

    if not start_pdb or not _os.path.isfile(start_pdb):
        return {"ok": False, "error": f"start_pdb 不存在: {start_pdb!r}", "diagnostics": diagnostics}

    # 用 inline PyRosetta 脚本跑 FlexPepDocking
    script = (
        "import json, sys, glob, os\n"
        "import pyrosetta\n"
        "from pyrosetta.rosetta.protocols.flexpep_docking import FlexPepDockingProtocol\n"
        "pyrosetta.init('-mute all -ex1 -ex2aro')\n"
        f"out_dir = {out_dir!r}\n"
        f"start_pdb = {start_pdb!r}\n"
        f"n_decoys = {n_decoys}\n"
        f"lowres = {lowres}\n"
        "os.makedirs(out_dir, exist_ok=True)\n"
        "pose0 = pyrosetta.pose_from_pdb(start_pdb)\n"
        "fpd = FlexPepDockingProtocol()\n"
        "fpd.set_lowres_abinitio(lowres)\n"
        "scores = []\n"
        "for i in range(n_decoys):\n"
        "    pose = pose0.clone()\n"
        "    try:\n"
        "        fpd.apply(pose)\n"
        "    except Exception as e:\n"
        "        scores.append({'idx': i, 'error': repr(e)}); continue\n"
        "    decoy_path = os.path.join(out_dir, f'decoy_{i:04d}.pdb')\n"
        "    pose.dump_pdb(decoy_path)\n"
        "    sc = pose.scores.get('total_score', 0.0)\n"
        "    scores.append({'idx': i, 'total_score': float(sc), 'path': decoy_path})\n"
        "scores.sort(key=lambda x: x.get('total_score', 1e9))\n"
        "summary = {'n_decoys': sum(1 for s in scores if 'error' not in s),\n"
        "           'best_score': scores[0].get('total_score', 0.0) if scores else 0.0,\n"
        "           'best_decoy_path': scores[0].get('path', '') if scores else '',\n"
        "           'top10': scores[:10]}\n"
        "json.dump(summary, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 7200)))
    diagnostics["subprocess"] = {"cmd": r.get("cmd")[:160], "wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "FlexPepDocking 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "stdout_head": r["stdout"][:300],
                "diagnostics": diagnostics}

    poses = [{"rank": i + 1, "affinity_kcal_per_mol": s.get("total_score", 0.0),
              "pose_path": s.get("path", "")} for i, s in enumerate(parsed.get("top10", []))]
    return {"ok": True, "skill_id": SKILL,
            "receptor": start_pdb, "ligand": peptide_chain,
            "best_affinity": parsed.get("best_score", 0.0),
            "poses": poses,
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "n_decoys_done": parsed.get("n_decoys")}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
